     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Context;
    11→
    12→    # Phase 1 polymorphic node classes
    13→    use Chalk::IR::Node::Base;
    14→    use Chalk::IR::Node::Constant;
    15→    use Chalk::IR::Node::Start;
    16→    use Chalk::IR::Node::Return;
    17→    use Chalk::IR::Node::Add;
    18→    use Chalk::IR::Node::Subtract;
    19→    use Chalk::IR::Node::Multiply;
    20→    use Chalk::IR::Node::Divide;
    21→    use Chalk::IR::Node::Negate;
    22→    use Chalk::IR::Node::Not;
    23→    use Chalk::IR::Node::PreIncrement;
    24→    use Chalk::IR::Node::PreDecrement;
    25→    use Chalk::IR::Node::PostIncrement;
    26→    use Chalk::IR::Node::PostDecrement;
    27→    use Chalk::IR::Node::Reference;
    28→    use Chalk::IR::Node::ScalarDeref;
    29→    use Chalk::IR::Node::VariableRead;
    30→    use Chalk::IR::Node::GT;
    31→    use Chalk::IR::Node::LT;
    32→    use Chalk::IR::Node::EQ;
    33→    use Chalk::IR::Node::NE;
    34→    use Chalk::IR::Node::LE;
    35→    use Chalk::IR::Node::GE;
    36→    use Chalk::IR::Node::If;
    37→    use Chalk::IR::Node::Proj;
    38→    use Chalk::IR::Node::Region;
    39→    use Chalk::IR::Node::Phi;
    40→    use Chalk::IR::Node::Loop;
    41→
    42→    field $graph :reader;
    43→    field $context :reader;  # Context-as-closure for variable memory
    44→    field $node_counter :reader = 0;
    45→    field $current_control :reader;  # Current control flow node
    46→    field $loop_depth = 0;   # Current loop nesting depth for label namespacing
    47→    field $loop_modified_vars = [];  # Stack of sets tracking modified vars per loop depth
    48→
    49→    ADJUST {
    50→        $graph = Chalk::IR::Graph->new();
    51→        $context = Chalk::IR::Context->empty_context();
    52→    }
    53→
    54→    # Generate unique node ID
    55→    method next_node_id() {
    56→        my $id = "node_$node_counter";
    57→        $node_counter++;
    58→        return $id;
    59→    }
    60→
    61→    # Set current control flow node
    62→    method set_control($ctrl) {
    63→        $current_control = $ctrl;
    64→    }
    65→
    66→    # Set context (for testing and manual context updates)
    67→    method set_context($ctx) {
    68→        $context = $ctx;
    69→    }
    70→
    71→    # Create Start node for a function/method
    72→    method build_start_node($function_name = 'main', $params = undef) {
    73→        $params //= [];
    74→        my $node_id = $self->next_node_id();
    75→        my $empty_inputs = [];
    76→        my $start = Chalk::IR::Node::Start->new(
    77→            id            => $node_id,
    78→            inputs        => $empty_inputs,
    79→            function_name => $function_name,
    80→            params        => $params,
    81→        );
    82→        $graph->add_node($start);
    83→
    84→        # Record transformation
    85→        $start->record_transform('ir_construction', 'Builder::build_start_node',
    86→            context => "function=$function_name"
    87→        );
    88→
    89→        $self->set_control($start->id);
    90→
    91→        # Create Proj nodes for each parameter and register in context
    92→        my $param_count = scalar($params->@*);
    93→        for my $i (0..($param_count - 1)) {
    94→            my $param_name = $params->[$i];
    95→            my $proj = $self->build_proj_node($start, $i, $param_name);
    96→            # Register parameter Proj in context with lexical: namespace
    97→            my $label = "lexical:$param_name";
    98→            $context = Chalk::IR::Context->extend_context($context, $label, $proj);
    99→        }
   100→
   101→        return $start;
   102→    }
   103→
   104→    # Create Constant node
   105→    method build_constant_node($value, $type = 'Int', $source_info = undef) {
   106→        die "build_constant_node: value is undefined" unless defined($value);
   107→
   108→        my $node_id = $self->next_node_id();
   109→        my $constant = Chalk::IR::Node::Constant->new(
   110→            id            => $node_id,
   111→            inputs        => [$current_control],
   112→            value         => $value,
   113→            type          => $type,
   114→            source_info   => $source_info,
   115→        );
   116→        $graph->add_node($constant);
   117→
   118→        # Record transformation
   119→        $constant->record_transform('ir_construction', 'Builder::build_constant_node',
   120→            context => "value=$value, type=$type"
   121→        );
   122→
   123→        return $constant;
   124→    }
   125→
   126→    # Create Return node
   127→    # If $control is undef, uses current_control. Otherwise uses provided control.
   128→    method build_return_node($value_node, $control = undef, $source_info = undef) {
   129→        die "build_return_node: value_node is undefined" unless defined($value_node);
   130→
   131→        # Check that value_node is an IR node object
   132→        my $ref_type = ref($value_node) || 'SCALAR';
   133→        my $prefix = substr($ref_type, 0, 15);
   134→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   135→        unless ($ref_type && $is_node) {
   136→            die "build_return_node: value_node is not an IR node object (got $ref_type)";
   137→        }
   138→
   139→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   140→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   141→
   142→        my $node_id = $self->next_node_id();
   143→        my $return = Chalk::IR::Node::Return->new(
   144→            id            => $node_id,
   145→            inputs        => [$ctrl, $value_node->id],
   146→            value_id      => $value_node->id,
   147→            control_id    => $ctrl,
   148→            source_info   => $source_info,
   149→        );
   150→        $graph->add_node($return);
   151→
   152→        # Record transformation
   153→        $return->record_transform('ir_construction', 'Builder::build_return_node',
   154→            context => "value_id=" . $value_node->id
   155→        );
   156→
   157→        return $return;
   158→    }
   159→
   160→    # Set control input for an existing node
   161→    method set_node_control($node, $control_id) {
   162→        my $inputs = $node->inputs;
   163→        $inputs->[0] = $control_id;  # Control is always first input
   164→    }
   165→
   166→    # Create arithmetic operation nodes
   167→    method build_add_node($left_node, $right_node, $source_info = undef) {
   168→        die "build_add_node: left_node is undefined" unless defined($left_node);
   169→        die "build_add_node: right_node is undefined" unless defined($right_node);
   170→        die "build_add_node: left_node is not an IR node object" unless ref($left_node) && ref($left_node) =~ /^Chalk::IR::Node/;
   171→        die "build_add_node: right_node is not an IR node object" unless ref($right_node) && ref($right_node) =~ /^Chalk::IR::Node/;
   172→
   173→        my $node_id = $self->next_node_id();
   174→        my $add = Chalk::IR::Node::Add->new(
   175→            id => $node_id,
   176→            inputs => [$current_control, $left_node->id, $right_node->id],
   177→            left_id => $left_node->id,
   178→            right_id => $right_node->id,
   179→            source_info => $source_info,
   180→        );
   181→        $graph->add_node($add);
   182→
   183→        # Record transformation
   184→        $add->record_transform('ir_construction', 'Builder::build_add_node',
   185→            context => "left_id=" . $left_node->id . ", right_id=" . $right_node->id
   186→        );
   187→
   188→        return $add;
   189→    }
   190→
   191→    method build_multiply_node($left_node, $right_node) {
   192→        my $node_id = $self->next_node_id();
   193→        my $mul = Chalk::IR::Node::Multiply->new(
   194→            id => $node_id,
   195→            inputs => [$current_control, $left_node->id, $right_node->id],
   196→            left_id => $left_node->id,
   197→            right_id => $right_node->id,
   198→        );
   199→        $graph->add_node($mul);
   200→
   201→        # Record transformation
   202→        $mul->record_transform('ir_construction', 'Builder::build_multiply_node',
   203→            context => "left_id=" . $left_node->id . ", right_id=" . $right_node->id
   204→        );
   205→
   206→        return $mul;
   207→    }
   208→
   209→    method build_sub_node($left_node, $right_node) {
   210→        my $node_id = $self->next_node_id();
   211→        my $sub = Chalk::IR::Node::Subtract->new(
   212→            id => $node_id,
   213→            inputs => [$current_control, $left_node->id, $right_node->id],
   214→            left_id => $left_node->id,
   215→            right_id => $right_node->id,
   216→        );
   217→        $graph->add_node($sub);
   218→
   219→        # Record transformation
   220→        $sub->record_transform('ir_construction', 'Builder::build_sub_node',
   221→            context => "left_id=" . $left_node->id . ", right_id=" . $right_node->id
   222→        );
   223→
   224→        return $sub;
   225→    }
   226→
   227→    method build_divide_node($left_node, $right_node) {
   228→        my $node_id = $self->next_node_id();
   229→        my $div = Chalk::IR::Node::Divide->new(
   230→            id => $node_id,
   231→            inputs => [$current_control, $left_node->id, $right_node->id],
   232→            left_id => $left_node->id,
   233→            right_id => $right_node->id,
   234→        );
   235→        $graph->add_node($div);
   236→
   237→        # Record transformation
   238→        $div->record_transform('ir_construction', 'Builder::build_divide_node',
   239→            context => "left_id=" . $left_node->id . ", right_id=" . $right_node->id
   240→        );
   241→
   242→        return $div;
   243→    }
   244→
   245→    # Generate label with loop depth if inside a loop
   246→    method make_variable_label($var_name) {
   247→        if ($loop_depth > 0) {
   248→            return "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   249→        }
   250→        return "lexical:$var_name";
   251→    }
   252→
   253→    # Create Store node (variable assignment)
   254→    method build_store_node($var_name, $value_node, $control = undef) {
   255→        # Store variable using lexical: namespace in context
   256→        # Inside loops, use loop depth in label: lexical:loop_0:$var
   257→        # Store the IR node object directly, not the node ID
   258→        my $label = $self->make_variable_label($var_name);
   259→        $context = Chalk::IR::Context->extend_context($context, $label, $value_node);
   260→
   261→        # Track this variable as modified if we're in a loop
   262→        if ($loop_depth > 0 && scalar($loop_modified_vars->@*) > 0) {
   263→            my $current_loop_vars = $loop_modified_vars->[-1];
   264→            $current_loop_vars->{$var_name} = 1;
   265→        }
   266→
   267→        return $value_node;
   268→    }
   269→
   270→    # Load node (variable read)
   271→    method build_load_node($var_name) {
   272→        # Retrieve variable using lexical: namespace from context
   273→        # Try loop-scoped label first, then fall back to outer scope
   274→        # Context now stores IR node objects directly, not node IDs
   275→        my $node;
   276→
   277→        # Try current loop depth first (search from innermost to outermost)
   278→        if ($loop_depth > 0) {
   279→            my $depth = $loop_depth - 1;
   280→            while ($depth >= 0) {
   281→                my $label = "lexical:loop_${depth}:$var_name";
   282→                $node = $context->($label);
   283→                last if defined($node);
   284→                $depth--;
   285→            }
   286→        }
   287→
   288→        # Fall back to non-loop lexical scope
   289→        $node //= $context->("lexical:$var_name");
   290→
   291→        # Return the node directly from context (no graph lookup needed)
   292→        return $node;
   293→    }
   294→
   295→    # Create Proj node (projection from MultiNode like Start)
   296→    method build_proj_node($source_node, $index, $label) {
   297→        my $node_id = $self->next_node_id();
   298→        my $proj = Chalk::IR::Node::Proj->new(
   299→            id            => $node_id,
   300→            inputs        => [$source_node->id],
   301→            index         => $index,
   302→            label         => $label,
   303→        );
   304→        $graph->add_node($proj);
   305→        return $proj;
   306→    }
   307→
   308→    # Comparison nodes
   309→    method build_greater_node($left_node, $right_node) {
   310→        my $node_id = $self->next_node_id();
   311→        my $cmp = Chalk::IR::Node::GT->new(
   312→            id            => $node_id,
   313→            inputs        => [$current_control, $left_node->id, $right_node->id],
   314→            left_id       => $left_node->id,
   315→            right_id      => $right_node->id,
   316→        );
   317→        $graph->add_node($cmp);
   318→        return $cmp;
   319→    }
   320→
   321→    method build_less_node($left_node, $right_node) {
   322→        my $node_id = $self->next_node_id();
   323→        my $cmp = Chalk::IR::Node::LT->new(
   324→            id            => $node_id,
   325→            inputs        => [$current_control, $left_node->id, $right_node->id],
   326→            left_id       => $left_node->id,
   327→            right_id      => $right_node->id,
   328→        );
   329→        $graph->add_node($cmp);
   330→        return $cmp;
   331→    }
   332→
   333→    method build_equal_node($left_node, $right_node) {
   334→        my $node_id = $self->next_node_id();
   335→        my $cmp = Chalk::IR::Node::EQ->new(
   336→            id            => $node_id,
   337→            inputs        => [$current_control, $left_node->id, $right_node->id],
   338→            left_id       => $left_node->id,
   339→            right_id      => $right_node->id,
   340→        );
   341→        $graph->add_node($cmp);
   342→        return $cmp;
   343→    }
   344→
   345→    method build_greater_or_equal_node($left_node, $right_node) {
   346→        my $node_id = $self->next_node_id();
   347→        my $cmp = Chalk::IR::Node::GE->new(
   348→            id            => $node_id,
   349→            inputs        => [$current_control, $left_node->id, $right_node->id],
   350→            left_id       => $left_node->id,
   351→            right_id      => $right_node->id,
   352→        );
   353→        $graph->add_node($cmp);
   354→        return $cmp;
   355→    }
   356→
   357→    method build_less_or_equal_node($left_node, $right_node) {
   358→        my $node_id = $self->next_node_id();
   359→        my $cmp = Chalk::IR::Node::LE->new(
   360→            id            => $node_id,
   361→            inputs        => [$current_control, $left_node->id, $right_node->id],
