   548→    # Loop depth tracking methods
   549→    method begin_loop_tracking() {
   550→        # Increment loop depth when entering a loop
   551→        $loop_depth++;
   552→        # Push a new set to track modified variables at this loop depth
   553→        push $loop_modified_vars->@*, {};
   554→        return;
   555→    }
   556→
   557→    method end_loop_tracking() {
   558→        # Decrement loop depth when exiting a loop
   559→        if ($loop_depth > 0) {
   560→            $loop_depth--;
   561→            # Pop the modified variables set for this loop
   562→            pop $loop_modified_vars->@* if scalar($loop_modified_vars->@*) > 0;
   563→        }
   564→        return;
   565→    }
   566→
   567→    method is_tracking_loop() {
   568→        return $loop_depth > 0;
   569→    }
   570→
   571→    method current_loop_depth() {
   572→        return $loop_depth;
   573→    }
   574→
   575→    method generate_loop_phi_nodes($loop_node) {
   576→        # Generate phi nodes for variables modified within the loop
   577→        # With context+labels approach, phi nodes are created for variables
   578→        # that exist both as 'lexical:$var' (pre-loop) and 'lexical:loop_N:$var' (in-loop)
   579→
   580→        my %phi_nodes;
   581→
   582→        # If we're not tracking a loop or have no modified vars, return empty
   583→        return \%phi_nodes unless scalar($loop_modified_vars->@*) > 0;
   584→
   585→        # Get the current loop's modified variables
   586→        my $modified_vars = $loop_modified_vars->[-1];
   587→
   588→        # For each modified variable, create a phi node
   589→        for my $var_name (keys($modified_vars->%*)) {
   590→            # Get pre-loop value (lexical:$var)
   591→            my $pre_loop_label = "lexical:$var_name";
   592→            my $pre_loop_value = $context->($pre_loop_label);
   593→
   594→            # Get loop-modified value (lexical:loop_N:$var where N = current depth - 1)
   595→            my $loop_label = "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   596→            my $loop_value = $context->($loop_label);
   597→
   598→            # Only create phi if both values exist
   599→            if (defined($pre_loop_value) && defined($loop_value)) {
   600→                # Build phi node with: control (loop), initial value, loop value
   601→                my $phi = $self->build_loop_phi_node(
   602→                    $loop_node,
   603→                    (ref($pre_loop_value) ? $pre_loop_value->id : $pre_loop_value),
   604→                    (ref($loop_value) ? $loop_value->id : $loop_value)
   605→                );
   606→                $phi_nodes{$var_name} = $phi;
   607→            }
   608→        }
   609→
   610→        return \%phi_nodes;
   611→    }
