   908→        my $node_id = $self->next_node_id();
   909→        my $str_length = Chalk::IR::Node->new(
   910→            id => $node_id,
   911→            op => 'StrLength',
   912→            inputs => [$current_control, $string_node->id],
   913→            attributes => $attributes,
   914→        );
   915→        $graph->add_node($str_length);
   916→        return $str_length;
   917→    }
   918→
   919→    method build_str_substr_node($string_node, $offset_node, $length_node) {
   920→        # Create StrSubstr node for extracting substring
   921→        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };
   922→        my $offset_ref = { op => 'NodeRef', node_id => $offset_node->id };
   923→        my $length_ref = { op => 'NodeRef', node_id => $length_node->id };
   924→
   925→        my $attributes = {
   926→            string => $string_ref,
   927→            offset => $offset_ref,
   928→            length => $length_ref
   929→        };
   930→
   931→        my $node_id = $self->next_node_id();
   932→        my $str_substr = Chalk::IR::Node->new(
   933→            id => $node_id,
   934→            op => 'StrSubstr',
   935→            inputs => [$current_control, $string_node->id, $offset_node->id, $length_node->id],
   936→            attributes => $attributes,
   937→        );
   938→        $graph->add_node($str_substr);
   939→        return $str_substr;
   940→    }
   941→
   942→    # Module system support (Issue #98 Phase 5)
   943→    method build_use_statement_node($type, $module, $imports) {
   944→        # Create UseStatement node for capturing use statement metadata
   945→        # $type: 'version', 'pragma', 'module', or 'external'
   946→        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
   947→        # $imports: arrayref of imported symbols (empty for full import)
   948→
   949→        my $graph = $self->graph;
   950→        my $current_control = $self->current_control;
   951→
   952→        my $attributes = {
   953→            type => $type,
   954→            module => $module,
   955→            imports => $imports
   956→        };
   957→
   958→        my $node_id = $self->next_node_id();
   959→        my $use_stmt = Chalk::IR::Node->new(
   960→            id => $node_id,
   961→            op => 'UseStatement',
   962→            inputs => [$current_control],
   963→            attributes => $attributes,
   964→        );
   965→        $graph->add_node($use_stmt);
   966→        return $use_stmt;
   967→    }
   968→
   969→    # Reference operations (Issue #130 Phase 4)
   970→
   971→    # Create reference to a scalar variable: \$x
   972→    method build_scalar_ref_node($var_name) {
   973→        my $label = "lexical:$var_name";
   974→        # Look up the target node (might be object or ID)
   975→        my $target_node_or_id = $context->($label);
   976→        die "Cannot create reference to undefined variable $var_name" unless defined($target_node_or_id);
   977→
   978→        # Get the node ID for the dependency
   979→        my $target_node_id = ref($target_node_or_id) ? $target_node_or_id->id : $target_node_or_id;
   980→
   981→        my $node_id = $self->next_node_id();
   982→        my $reference = Chalk::IR::Node::Reference->new(
   983→            id             => $node_id,
   984→            inputs         => [$current_control, $target_node_id],  # Add target as dependency
   985→            target_context => $context,
   986→            target_label   => $label,
   987→        );
   988→        $graph->add_node($reference);
   989→        return $reference;
   990→    }
   991→
   992→    # Create reference to array element: \$arr[1]
   993→    method build_element_ref_node($collection_name, $index_node) {
   994→        # Get the collection from context (might be object or ID)
   995→        my $collection_label = "lexical:$collection_name";
   996→        my $collection_node_or_id = $context->($collection_label);
   997→
   998→        # Get the collection node
   999→        my $collection_node;
  1000→        if (ref($collection_node_or_id)) {
  1001→            $collection_node = $collection_node_or_id;
  1002→        } else {
  1003→            $collection_node = $graph->get_node($collection_node_or_id);
  1004→        }
  1005→
  1006→        # Get the array context from the collection node
  1007→        my $array_ctx = $collection_node->array_context;
  1008→
  1009→        # Get the index value - need to evaluate it
  1010→        # For now, assume it's a constant node
  1011→        my $index_val = $index_node->value;
  1012→
  1013→        # Create the reference pointing to the array context with index: label
  1014→        my $label = Chalk::IR::Context->make_index_label($index_val);
  1015→        my $node_id = $self->next_node_id();
  1016→        my $reference = Chalk::IR::Node::Reference->new(
  1017→            id             => $node_id,
  1018→            inputs         => [$current_control, $collection_node->id, $index_node->id],
  1019→            target_context => $array_ctx,
  1020→            target_label   => $label,
  1021→        );
  1022→        $graph->add_node($reference);
  1023→        return $reference;
  1024→    }
  1025→
  1026→    # Dereference a scalar reference: $$ref
  1027→    method build_scalar_deref_node($ref_var_name) {
  1028→        # Get the reference from context (might be object or ID)
  1029→        my $ref_label = "lexical:$ref_var_name";
  1030→        my $ref_node_or_id = $context->($ref_label);
  1031→
  1032→        # Get the node ID
  1033→        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;
  1034→
  1035→        # Create ScalarDeref node
  1036→        my $node_id = $self->next_node_id();
  1037→        my $deref = Chalk::IR::Node::ScalarDeref->new(
  1038→            id      => $node_id,
  1039→            inputs  => [$current_control, $ref_id],
  1040→            ref_id  => $ref_id,
  1041→        );
  1042→        $graph->add_node($deref);
  1043→        return $deref;
  1044→    }
  1045→
  1046→    # Read variable from context: helper for tests
  1047→    method build_variable_read_node($var_name) {
  1048→        my $label = "lexical:$var_name";
  1049→        my $node_id = $self->next_node_id();
  1050→        my $var_read = Chalk::IR::Node::VariableRead->new(
  1051→            id        => $node_id,
  1052→            inputs    => [$current_control],
  1053→            var_label => $label,
  1054→        );
  1055→        $graph->add_node($var_read);
  1056→        return $var_read;
  1057→    }
  1058→
  1059→    # Assign through a dereferenced reference: $$ref = value
  1060→    method build_scalar_deref_assign_node($ref_var_name, $value_node) {
  1061→        # Get the reference from context
  1062→        my $ref_label = "lexical:$ref_var_name";
  1063→        my $ref_node_or_id = $context->($ref_label);
  1064→
  1065→        # Might be node object or node ID depending on when it was stored
  1066→        my $ref_node;
  1067→        if (ref($ref_node_or_id)) {
  1068→            $ref_node = $ref_node_or_id;
  1069→        } else {
  1070→            $ref_node = $graph->get_node($ref_node_or_id);
  1071→        }
  1072→
  1073→        # Get the target label from the reference
  1074→        my $target_label = $ref_node->target_label;
  1075→
  1076→        # Extend the BUILDER's current context with the new value (node object, not ID)
  1077→        # This updates the variable that the reference points to
  1078→        $context = Chalk::IR::Context->extend_context(
  1079→            $context,
  1080→            $target_label,
  1081→            $value_node
  1082→        );
  1083→
  1084→        # Return the value node for chaining
  1085→        return $value_node;
  1086→    }
  1087→
  1088→}
  1089→
  1090→1;
  1091→

