     8→class Chalk::IR::Optimizer::GVN {
     9→    use Chalk::IR::Node;
    10→    use Chalk::IR::Graph;
    11→
    12→    # Instance method for pipeline compatibility
    13→    # Returns optimized graph (not a hashref)
    14→    method apply($graph) {
