    18→
    19→    # Run Global Value Numbering optimization pass
    20→    # Returns: { graph => optimized_graph, metrics => { nodes_eliminated => N, redirections => {...} } }
    21→    sub run_gvn($class, $graph) {
    22→        # Value number tracking: value_number => canonical_node_id
    23→        my $value_to_node = {};
    24→
    25→        # Node to value number mapping: node_id => value_number
    26→        my $node_to_value = {};
    27→
    28→        # Redirection map: duplicate_node_id => canonical_node_id
    29→        my $redirections = {};
    30→
    31→        # Get all nodes in a consistent order (we'll process them by ID order)
    32→        my @node_ids = sort keys %{$graph->nodes};
    33→
    34→        # Phase 1: Compute value numbers for all nodes
    35→        for my $node_id (@node_ids) {
    36→            my $node = $graph->get_node($node_id);
    37→            next unless defined($node);
    38→
    39→            # Compute value number for this node
    40→            my $value_num = $class->_compute_value_number($node, $node_to_value, $graph);
    41→
    42→            # Check if we've seen this value number before
    43→            if (exists($value_to_node->{$value_num})) {
    44→                # Found a duplicate! Record the redirection
    45→                my $canonical_id = $value_to_node->{$value_num};
    46→                $redirections->{$node_id} = $canonical_id;
    47→                # Use the canonical node's value number for this node too
    48→                $node_to_value->{$node_id} = $value_num;
    49→            } else {
    50→                # First time seeing this value - this is the canonical node
    51→                $value_to_node->{$value_num} = $node_id;
    52→                $node_to_value->{$node_id} = $value_num;
    53→            }
    54→        }
    55→
    56→        # Phase 2: Build new graph with redirections applied
    57→        my $new_graph = Chalk::IR::Graph->new();
    58→
    59→        # Track which nodes have been copied to new graph
    60→        my %copied;
    61→
    62→        # Copy nodes that aren't redirected, applying redirections to inputs
    63→        for my $node_id (@node_ids) {
    64→            # Skip nodes that are being redirected away
    65→            next if exists($redirections->{$node_id});
    66→
    67→            my $old_node = $graph->get_node($node_id);
    68→            next unless defined($old_node);
    69→
    70→            # Apply redirections to input list
    71→            my @new_inputs;
    72→            for my $input_id ($old_node->inputs->@*) {
    73→                if (defined($input_id)) {
    74→                    # Follow redirection chain if this input was redirected
    75→                    my $final_id = $class->_follow_redirections($input_id, $redirections);
    76→                    push @new_inputs, $final_id;
    77→                } else {
    78→                    push @new_inputs, undef;
    79→                }
    80→            }
    81→
    82→            # Apply redirections to attributes (if they contain node references)
    83→            my $new_attributes = $class->_redirect_attributes(
    84→                $old_node->attributes,
    85→                $redirections
    86→            );
    87→
    88→            # Reconstruct node preserving polymorphic type
    89→            # Use from_hash() factory to create correct node class
    90→            my $new_node = Chalk::IR::Node->from_hash({
    91→                id         => $node_id,
    92→                op         => $old_node->op,
    93→                inputs     => \@new_inputs,
    94→                attributes => $new_attributes,
    95→            });
    96→
    97→            $new_graph->add_node($new_node);
    98→            $copied{$node_id} = 1;
    99→        }
   100→
   101→        # Preserve entry point (following any redirection)
   102→        if (defined($graph->entry)) {
   103→            my $new_entry = $class->_follow_redirections($graph->entry, $redirections);
   104→            $new_graph->set_entry($new_entry);
   105→        }
   106→
   107→        # Compute metrics
   108→        my $nodes_eliminated = scalar keys %{$redirections};
   109→
   110→        return {
   111→            graph => $new_graph,
   112→            metrics => {
   113→                nodes_eliminated => $nodes_eliminated,
   114→                redirections => $redirections,
   115→            }
   116→        };
   117→    }
   118→
   119→    # Compute value number for a node
   120→    # Returns a string that uniquely identifies the value computed by this node
   121→    sub _compute_value_number($class, $node, $node_to_value, $graph) {
   122→        my $op = $node->op;
   123→        my $attrs = $node->attributes;
   124→
   125→        # Special case: Constants
   126→        if ($op eq 'Constant') {
   127→            my $value = $attrs->{value} // '';
   128→            my $type = $attrs->{type} // '';
   129→            return "Constant:$value:$type";
   130→        }
   131→
   132→        # Special case: Proj nodes (include index)
   133→        if ($op eq 'Proj') {
   134→            my $index = $attrs->{index} // '';
   135→            # Get value number of input node
   136→            my @input_vns;
   137→            for my $input_id ($node->inputs->@*) {
   138→                if (defined($input_id) && exists($node_to_value->{$input_id})) {
   139→                    push @input_vns, $node_to_value->{$input_id};
   140→                } else {
   141→                    push @input_vns, $input_id // 'undef';
   142→                }
   143→            }
   144→            my $inputs_str = join(',', @input_vns);
   145→            return "Proj:$index:$inputs_str";
   146→        }
   147→
   148→        # Special case: Phi nodes - use identity-based comparison
   149→        # Only merge if ALL inputs are identical
   150→        if ($op eq 'Phi') {
   151→            # For Phi nodes, we use the actual input IDs rather than value numbers
   152→            # This is conservative but correct
   153→            my $inputs_str = join(',', map { $_ // 'undef' } $node->inputs->@*);
   154→            my $region_id = $attrs->{region_id} // '';
   155→            return "Phi:$region_id:$inputs_str";
   156→        }
   157→
   158→        # General case: Operations
   159→        # Get value numbers of inputs
   160→        my @input_vns;
   161→        for my $input_id ($node->inputs->@*) {
   162→            if (defined($input_id) && exists($node_to_value->{$input_id})) {
   163→                push @input_vns, $node_to_value->{$input_id};
   164→            } else {
   165→                push @input_vns, $input_id // 'undef';
   166→            }
   167→        }
   168→
   169→        # Handle commutativity for Add and Multiply
   170→        if ($op eq 'Add' || $op eq 'Multiply') {
   171→            @input_vns = sort @input_vns;
   172→        }
   173→
   174→        my $inputs_str = join(',', @input_vns);
   175→        return "$op:$inputs_str";
   176→    }
   177→
   178→    # Follow a chain of redirections to find the final canonical node
   179→    sub _follow_redirections($class, $node_id, $redirections) {
   180→        my $current = $node_id;
   181→        my %seen;
   182→
   183→        while (exists($redirections->{$current})) {
   184→            # Detect cycles (shouldn't happen, but be safe)
   185→            return $node_id if exists($seen{$current});
   186→            $seen{$current} = 1;
   187→
   188→            $current = $redirections->{$current};
   189→        }
   190→
   191→        return $current;
   192→    }
   193→
   194→    # Apply redirections to node attributes (which may contain node references)
   195→    sub _redirect_attributes($class, $attrs, $redirections) {
   196→        return {} unless defined($attrs);
