   201→            my $value = $attrs->{$key};
   202→
   203→            # If this is a hash ref, it might be a NodeRef
   204→            if (ref($value) eq 'HASH') {
   205→                # Check if it's a NodeRef
   206→                if (exists($value->{op}) && $value->{op} eq 'NodeRef') {
   207→                    my $node_id = $value->{node_id};
   208→                    if (defined($node_id) && exists($redirections->{$node_id})) {
   209→                        # Redirect the NodeRef
   210→                        $new_attrs{$key} = {
   211→                            $value->%*,
   212→                            node_id => $redirections->{$node_id}
   213→                        };
   214→                    } else {
   215→                        $new_attrs{$key} = $value;
   216→                    }
   217→                } else {
   218→                    # Just copy the hash as-is
   219→                    $new_attrs{$key} = $value;
   220→                }
   221→            }
