   223→            # This handles: store_id, left_id, right_id, value_id, control_id, region_id, etc.
   224→            elsif (length($key) >= 3 && substr($key, -3) eq '_id' && defined($value) && exists($redirections->{$value})) {
   225→                $new_attrs{$key} = $redirections->{$value};
   226→            }
   227→            else {
   228→                # Copy as-is for other types
   229→                $new_attrs{$key} = $value;
   230→            }
   231→        }
   232→
